double h = (b - a) / N;
double x1 = a;
double x2 = a + h;
double sum = 0.0;
for (int i = 0; i < N; i++) {
    double midpoint = (x1 + x2) / 2.0;
    sum += h * f(midpoint);
    x1 += h;
    x2 += h;
}
return sum;

